#include "Music.c"
#include <stddef.h>
#include <math.h>
int main(int argc,char**argv){int e;BlitzMusic*m=blitz_music_create(argv[1],&e);if(!m)return 1;int effects[256]={0},samples=0;size_t sampleBytes=0;for(int p=0;p<m->song->header->numPat;p++){PatData*pat=m->song->partition[p];for(int ch=0;ch<4;ch++)for(int row=0;row<pat->header.size;row++){Cmd*c=GetMADCommand(row,ch,pat);if(c->cmd||c->arg)effects[c->cmd]++;}}for(int i=0;i<MAXINSTRU*MAXSAMPLE;i++)if(m->song->sample[i]){samples++;sampleBytes+=m->song->sample[i]->size;}printf("samples=%d sampleBytes=%zu oldHeader=%zu instrumentHeader=%zu sampleHeader=%zu\n",samples,sampleBytes,sizeof(oldMADSpec),sizeof(oldInstrData),sizeof(oldsData));for(int i=0;i<256;i++)if(effects[i])printf("effect %x = %d\n",i,effects[i]);float left[1024],right[1024];unsigned hash=2166136261u;double sum=0;for(int j=0;j<10400;j++){blitz_music_render(m,left,right,1024);for(int i=0;i<1024;i++){sum+=left[i]*left[i]+right[i]*right[i];uint32_t v;memcpy(&v,&left[i],4);hash=(hash^v)*16777619u;}}printf("241-second render RMS=%f hash=%08x order=%d row=%d\n",sqrt(sum/(10400*1024*2)),hash,m->driver->base.PL,m->driver->base.PartitionReader);blitz_music_destroy(m);return 0;}
